// newTitleAPI builds a handler over a fresh store holding one serial library
// with one series and one episode item, and returns the router, the store,
// the library id, the series row (minted ser_ id), and the episode item id.
func newTitleAPI(t *testing.T) (http.Handler, *store.Store, int64, string, string) {
	t.Helper()
	st := openAPIStore(t)
	ctx := context.Background()
	libID, err := st.CreateLibrary(ctx, "serial", "/media/titles", "Titles")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	series := seedSeries(t, st, libID, "Show",
		`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`, "ready")
	seedItem(t, st, libID, "ep1", "Show/Show S01E01.mkv")
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})
	return h, st, libID, series.ID, "itm_ep1"
}

