// TestTitleOverrideVerbs covers the title routes end to end (serial-watch-flow
// 2.1 + 2.2): the PUT/DELETE round trip over both id spaces riding the wire on
// every read surface (series list/detail, items list/detail, episodes), the
// admin-group gate, and the validation contract — whitespace-only and
// non-string titles 400, unknown ids 404, nothing written in any case.
func TestTitleOverrideVerbs(t *testing.T) {

	t.Run("put_round_trip_rides_the_wire", func(t *testing.T) {
		h, _, libID, seriesID, itemID := newTitleAPI(t)

		// PUT a series title: 200 with the stored record.
		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/"+seriesID+"/title", `{"title":"Better Name"}`, adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("series PUT status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var rec titleOverrideDTO
		if err := json.NewDecoder(resp.Body).Decode(&rec); err != nil {
			t.Fatalf("decode titleOverrideDTO: %v", err)
		}
		resp.Body.Close()
		if rec.EntityID != seriesID || rec.Title != "Better Name" || rec.UpdatedAt == "" {
			t.Fatalf("stored record = %+v, want the series entity with title and stamp", rec)
		}

		// The series reads follow: detail and list carry the override.
		detail := doRequest(t, h, http.MethodGet, "/api/v1/series/"+seriesID, "", adminToken)
		var dr seriesResponse
		if err := json.NewDecoder(detail.Body).Decode(&dr); err != nil {
			t.Fatalf("decode seriesResponse: %v", err)
		}
		detail.Body.Close()
		if dr.Series.TitleOverride != "Better Name" {
			t.Fatalf("series detail title_override = %q, want the stored title", dr.Series.TitleOverride)
		}
		listing := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(libID), "", adminToken)
		var lr seriesListResponse
		if err := json.NewDecoder(listing.Body).Decode(&lr); err != nil {
			t.Fatalf("decode seriesListResponse: %v", err)
		}
		listing.Body.Close()
		if len(lr.Items) != 1 || lr.Items[0].TitleOverride != "Better Name" {
			t.Fatalf("series list title_override = %+v, want the stored title on the row", lr.Items)
		}

		// The same round trip over the item id space.
		putTitle(t, h, "/api/v1/items/"+itemID+"/title", `{"title":"Ep One Renamed"}`, adminToken, http.StatusOK, "")
		idetail := doRequest(t, h, http.MethodGet, "/api/v1/items/"+itemID, "", adminToken)
		var ir itemResponse
		if err := json.NewDecoder(idetail.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemResponse: %v", err)
		}
		idetail.Body.Close()
		if ir.Item.TitleOverride != "Ep One Renamed" {
			t.Fatalf("item detail title_override = %q, want the stored title", ir.Item.TitleOverride)
		}
		// The episodes list is an items list: it carries the override too.
		eps := doRequest(t, h, http.MethodGet, "/api/v1/series/"+seriesID+"/episodes", "", adminToken)
		var er itemsResponse
		if err := json.NewDecoder(eps.Body).Decode(&er); err != nil {
			t.Fatalf("decode itemsResponse: %v", err)
		}
		eps.Body.Close()
		if len(er.Items) != 1 || er.Items[0].TitleOverride != "Ep One Renamed" {
			t.Fatalf("episodes title_override = %+v, want the stored title on the episode row", er.Items)
		}

		// DELETE the item's override: 204, and the reads fall back to empty
		// while the series override survives (per-entity rows).
		resp = doRequest(t, h, http.MethodDelete, "/api/v1/items/"+itemID+"/title", "", adminToken)
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("item DELETE status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		after := doRequest(t, h, http.MethodGet, "/api/v1/items/"+itemID, "", adminToken)
		var afterBody itemResponse
		if err := json.NewDecoder(after.Body).Decode(&afterBody); err != nil {
			t.Fatalf("decode itemResponse after delete: %v", err)
		}
		after.Body.Close()
		if afterBody.Item.TitleOverride != "" {
			t.Fatalf("item title_override after delete = %q, want empty", afterBody.Item.TitleOverride)
		}
		sdetail := doRequest(t, h, http.MethodGet, "/api/v1/series/"+seriesID, "", adminToken)
		var sdr seriesResponse
		if err := json.NewDecoder(sdetail.Body).Decode(&sdr); err != nil {
			t.Fatalf("decode seriesResponse: %v", err)
		}
		sdetail.Body.Close()
		if sdr.Series.TitleOverride != "Better Name" {
			t.Fatalf("series title_override = %q, want it to survive the item delete", sdr.Series.TitleOverride)
		}
	})

	t.Run("delete_is_idempotent", func(t *testing.T) {
		h, _, _, seriesID, _ := newTitleAPI(t)
		for i := 0; i < 2; i++ {
			resp := doRequest(t, h, http.MethodDelete, "/api/v1/series/"+seriesID+"/title", "", adminToken)
			resp.Body.Close()
			if resp.StatusCode != http.StatusNoContent {
				t.Fatalf("DELETE #%d status = %d, want %d (idempotent)", i+1, resp.StatusCode, http.StatusNoContent)
			}
		}
	})

	t.Run("validation_writes_nothing", func(t *testing.T) {
		h, st, _, seriesID, itemID := newTitleAPI(t)

		// Whitespace-only and non-string titles: 400 bad_request, even against
		// real entities.
		putTitle(t, h, "/api/v1/series/"+seriesID+"/title", `{"title":"   "}`, adminToken,
			http.StatusBadRequest, "bad_request")
		putTitle(t, h, "/api/v1/items/"+itemID+"/title", `{"title":42}`, adminToken,
			http.StatusBadRequest, "bad_request")
		putTitle(t, h, "/api/v1/series/"+seriesID+"/title", `{}`, adminToken,
			http.StatusBadRequest, "bad_request")
		// Unknown ids on both id spaces: 404 not_found.
		putTitle(t, h, "/api/v1/series/ser_999_deadbeefdeadbeef/title", `{"title":"X"}`, adminToken,
			http.StatusNotFound, "not_found")
		putTitle(t, h, "/api/v1/items/itm_ghost/title", `{"title":"X"}`, adminToken,
			http.StatusNotFound, "not_found")

		// Nothing was written in any of the cases: no row for the real
		// entities the invalid bodies targeted, none for the ghosts.
		for _, id := range []string{seriesID, itemID, "ser_999_deadbeefdeadbeef", "itm_ghost"} {
			if storedOverrideExists(t, st, id) {
				t.Fatalf("title override exists for %s, want none (rejected requests write nothing)", id)
			}
		}
	})

	t.Run("admin_group_gated", func(t *testing.T) {
		h, st, _, seriesID, _ := newTitleAPI(t)

		// No token: 401 before any handler logic (authN precedes authZ).
		resp := doRequest(t, h, http.MethodPut, "/api/v1/series/"+seriesID+"/title", `{"title":"X"}`, "")
		resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("unauthenticated PUT status = %d, want %d", resp.StatusCode, http.StatusUnauthorized)
		}
		// Client role: 403 (the title routes are operator mutations, admin
		// group), exercised via the synthetic-principal injector over the REAL
		// mountV1Routes wiring (the TestNew_RoleGating seam).
		client := gatingRouter(Deps{AdminToken: adminToken, Store: st,
			Scan: func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
		}, RoleClient)
		resp = doRequest(t, client, http.MethodPut, "/api/v1/series/"+seriesID+"/title", `{"title":"X"}`, "no-authmw")
		resp.Body.Close()
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("client-role PUT status = %d, want %d", resp.StatusCode, http.StatusForbidden)
		}
		// Neither call left a side effect.
		if storedOverrideExists(t, st, seriesID) {
			t.Fatal("title override exists after gated calls, want none")
		}
	})
}
